package com.nobodiiiii.createbiotech.content.biocomputing.editor;
import static org.junit.jupiter.api.Assertions.*;import com.nobodiiiii.createbiotech.content.biocomputing.computer.ComputerRuntime;import com.nobodiiiii.createbiotech.content.biocomputing.computation.*;import java.util.*;import org.junit.jupiter.api.Test;
class ComputerStatusViewTest{@Test void exposesInstallationDiagnosticSeparatelyFromMachineDiagnostic(){var draft=new ProgramDraft();String n=draft.add(ProgramDraftTest.number(1),0,0);draft.output("x",n);var machine=new MachineCheckpoint(new DataValue.RecordValue(Map.of()),ComputationMachine.Status.IDLE,false,0,0,Optional.empty(),Optional.empty(),List.of());var install=new ComputationMachine.Diagnostic(ComputationException.Code.TYPE_MISMATCH,"installation","stored cell changed");var snapshot=new ComputerRuntime.Snapshot(UUID.randomUUID(),draft.snapshot(),machine,Optional.empty(),Optional.of(install));var view=ComputerStatusView.of(snapshot);assertEquals(DataValue.NullValue.INSTANCE,view.field("diagnostic"));var detail=(DataValue.RecordValue)view.field("installation_diagnostic");assertEquals(new DataValue.TextValue("stored cell changed"),detail.field("message"));}}
